import urllib.parse

def is_allowed_url(url, allowed_hosts):
    """Return True iff url is an http(s) URL whose host is in allowed_hosts."""
    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme in ('http', 'https') and parsed.hostname in allowed_hosts:
            return True
    except ValueError:
        pass
    return False
